    23  static vcardstructuredtype *vcardstructured_alloc(void)
    24  {
    25      struct vcardstructuredtype_impl *st;
    26
    27      st = icalmemory_new_buffer(sizeof(struct vcardstructuredtype_impl));
    28      if (!st) {
    29          icalerror_set_errno(ICAL_NEWFAILED_ERROR);
    30          return NULL;
    31      }
    32      memset(st, 0, sizeof(struct vcardstructuredtype_impl));
    33
    34      return st;
    35  }
    36
    37  static void vcardstructured_free(vcardstructuredtype *st)
    38  {
    39      for (size_t i = 0; i < st->num_fields; i++) {
    40          if (st->field[i]) {
    41              vcardstrarray_free(st->field[i]);
    42          }
    43      }
    44      icalmemory_free_buffer((void *)st);
    45  }
    46
    47  vcardstructuredtype *vcardstructured_new(size_t num_fields)
    48  {
    49      struct vcardstructuredtype_impl *st = vcardstructured_alloc();
    50      if (!st) {
    51          return st;
    52      }
    53      vcardstructured_ref(st);
    54
    55      st->num_fields = num_fields;
    56      return st;
    57  }
    58
    59  vcardstructuredtype *vcardstructured_new_from_string(const char *str)
    60  {
    61      struct vcardstructuredtype_impl *st = vcardstructured_alloc();
    62      if (!st) {
    63          return st;
    64      }
    65      vcardstructured_ref(st);
    66
    67      vcardstrarray *field = vcardstrarray_new(2);
    68      st->field[st->num_fields++] = field;
    69
    70      do {
    71          char *dequoted_str = vcardvalue_strdup_and_dequote_text(&str, ",;");
    72
    73          if (*str == ',' || field->num_elements || strlen(dequoted_str)) {
    74              vcardstrarray_append(field, dequoted_str);
    75          }
    76          icalmemory_free_buffer(dequoted_str);
    77
    78          if (*str == ';') {
    79              /* end of field */
    80              field = vcardstrarray_new(2);
    81              st->field[st->num_fields++] = field;
    82          }
    83
    84      } while (*str++ != '\0');
    85
    86      return st;
    87  }
    88
    89  void vcardstructured_ref(vcardstructuredtype *st)
    90  {
    91      icalerror_check_arg_rv((st != NULL), "st");
    92
    93      st->refcount++;
    94  }
    95
    96  void vcardstructured_unref(vcardstructuredtype *st)
    97  {
    98      icalerror_check_arg_rv((st != NULL), "st");
    99      icalerror_check_arg_rv((st->refcount > 0), "st->refcount > 0");
   100
   101      st->refcount--;
   102
   103      if (st->refcount != 0) {
   104          return;
   105      }
   106
   107      vcardstructured_free(st);
   108  }
   109
   110  vcardstructuredtype *vcardstructured_clone(const vcardstructuredtype *st)
   111  {
   112      icalerror_check_arg_rz((st != NULL), "st");
   113
   114      struct vcardstructuredtype_impl *clone_st = vcardstructured_alloc();
   115      if (!clone_st) {
   116          return NULL;
   117      }
   118      vcardstructured_ref(clone_st);
   119
   120      clone_st->num_fields = st->num_fields;
   121
   122      for (size_t i = 0; i < st->num_fields; i++) {
   123          clone_st->field[i] = vcardstrarray_clone(st->field[i]);
   124      }
   125
   126      return clone_st;
   127  }
   128
   129  size_t vcardstructured_num_fields(const vcardstructuredtype *st)
   130  {
   131      icalerror_check_arg_rz((st != NULL), "st");
   132      return st->num_fields;
   133  }
   134
   135  void vcardstructured_set_num_fields(vcardstructuredtype *st,
   136                                      size_t num_fields)
   137  {
   138      icalerror_check_arg_rv((st != NULL), "st");
   139
   140      for (size_t i = num_fields; i < st->num_fields; i++) {
   141          vcardstrarray_free(st->field[i]);
   142      }
   143
   144      st->num_fields = num_fields;
   145  }
   146
   147  vcardstrarray *vcardstructured_field_at(const vcardstructuredtype *st,
   148                                          size_t position)
   149  {
   150      icalerror_check_arg_rz((st != NULL), "st");
   151      icalerror_check_arg_rz((st->num_fields > position), "position");
   152
   153      return st->field[position];
   154  }
   155
   156  void vcardstructured_set_field_at(vcardstructuredtype *st,
   157                                    size_t position,
   158                                    vcardstrarray *field)
   159  {
   160      icalerror_check_arg_rv((st != NULL), "st");
   161
   162      if (position >= st->num_fields) {
   163          vcardstructured_set_num_fields(st, position + 1);
   164      }
   165
   166      vcardstrarray_free(st->field[position]);
   167      st->field[position] = field;
   168  }
